// non-secret choices load_agent_runtime() reads on the next launch.
AgentSetupServicePtr make_agent_setup(AppConfig* config);

// Signing in to a JusPrin account: the account is stored where the Agent's
// keys are, and signing in makes it the Agent's provider.
CloudSignInPtr make_cloud_sign_in(AppConfig* config);
// Where "Get more credits" goes, on the server the account signs in to.
std::string cloud_pricing_url(const AppConfig* config);
// Where a print report goes, and the account's token; empty when signed out.
std::string cloud_print_reports_url(const AppConfig* config);
std::string cloud_account_token(const AppConfig* config);

// The docked Agent's per-chat models: every provider with a stored key, the
// default provider setup recorded, agents built from those keys, and each
// provider's model list fetched from the provider. `post` runs a callback on
// the GUI thread; the lists arrive through it.
std::shared_ptr<IChatModelSource> make_chat_model_source(AppConfig* config,
                                                         std::function<void(std::function<void()>)> post);

} // namespace Slic3r::GUI::JusPrin::Agent
    }

    std::string model_format(const std::string& provider, const std::string& model) const override
    {
        return stored_format(m_config, provider, model);
    }

    void fetch_account(AccountDone done) override
    {
        for (const std::string& provider : configured_providers()) {
            const ProviderProfile* profile = profile_for(provider);
            if (profile == nullptr || !profile->account_sign_in)
                continue;
            Agent::fetch_account(*profile, load_provider_api_key(m_config, provider), endpoint_for(m_config, *profile), m_cancelled,
                                 [post = m_post, done = std::move(done)](std::optional<nlohmann::json> account) {
                                     post([done, account = std::move(account)]() mutable { done(std::move(account)); });
                                 });
            return;
        }
        done(std::nullopt);
    }

    void list_models(const std::string& provider, ModelsDone done) override
    {
        const ProviderProfile* profile = profile_for(provider);
        const std::string      key     = load_provider_api_key(m_config, provider);
{
    bool                     ok{false};
    std::vector<ModelOption> models;
    std::string              error; // for the log; the page shows its own words
};

// Fetches every page of the list on Http's own thread and calls `done` there
// once. Setting `*cancelled` stops it; `done` is then not called.
// The signed-in account's credits, plan and usage; nothing when they could not
// be read. `done` runs on the request's thread.
void fetch_account(const ProviderProfile& profile, const std::string& api_key, const std::string& endpoint_override,
                   std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(std::optional<nlohmann::json>)> done);

void fetch_model_list(const ProviderProfile& profile, const std::string& api_key, const std::string& endpoint_override,
                      std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(ModelListResult)> done);

} // namespace Slic3r::GUI::JusPrin::Agent
