#pragma once

// What Home needs from the application, in the fork's own vocabulary.
//
// The Agent side of the shell reaches OrcaSlicer through Workspace::IWorkspace
// with OrcaWorkspaceAdapter behind it; this is the same seam for Home. Orca
// types stop at the adapter: HomeHost sees only the structs in
// HomeSnapshot.hpp, which is what lets its protocol handling be tested without
// a GUI, and what keeps the churn in MainFrame and the device layer to one
// file instead of spread through the host.

#include "HomeSnapshot.hpp"

#include <nlohmann/json.hpp>

#include <functional>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

// One file dropped on the page: its name as the page saw it, and its bytes.
struct DroppedFile
{
    std::string name;
    std::string bytes;
};

class IHomeBackend
{
public:
    virtual ~IHomeBackend() = default;

    // Reads. Called whenever Home is shown or asks for state.
    virtual bool                      dark() const              = 0;
    virtual ProjectList               recent_projects() const   = 0;
    virtual std::vector<PrinterEntry> printers() const          = 0;
    virtual Snapshot::Onboarding onboarding()                   = 0;

    // Actions. Each is the whole product gesture, not a step of one, so the
    // adapter can use whichever upstream entry point already performs it.
    virtual void open_project(const std::string& project_id)    = 0;
    // A blank project, for a print built up part by part.
    virtual void new_project()                                  = 0;
    // A file from the OS file dialog, opened as a new project the way a file
    // opened from Finder or Explorer is; cancelling leaves Home as it is.
    virtual void open_file()                                    = 0;
    // Files dropped on the page, which hands over their names and bytes but
    // not where they came from; opened as open_file opens one.
    virtual void open_dropped_files(const std::vector<DroppedFile>& files) = 0;
    virtual void launch_monitor(const std::string& printer_id)  = 0;
    virtual void add_printer()                                  = 0;
    // JusPrin's Preferences window, over Home.
    virtual void open_preferences() {}

    // The Print history screen. Its entries, every project's, with each
    // exported file checked against what was written (PrintHistory.hpp).
    virtual nlohmann::json print_history() { return nlohmann::json::array(); }
    // Back from a Print history the project opened: to the project's screen.
    virtual void leave_print_history() {}
    // The project's chat at the marker where the G-code went out.
    virtual void open_in_chat(const std::string& project_id, const std::string& conversation_id,
                              const std::string& marker_id) {}
    // The project's kept copy of a G-code, written where the person picks,
    // or, with `beside`, next to that earlier export under a name no file has.
    virtual void export_gcode(const std::string& project_id, const std::string& hash, const std::string& beside) {}
    // OrcaSlicer's send dialog for the kept file of a recorded G-code.
    virtual void print_again(const std::string& project_id, const std::string& hash) {}

    // Print reports (boards 8a to 8d), which need the person's account.
    virtual bool reports_offered() const { return false; }
    // The OS file dialog; nothing when the person cancels.
    virtual std::optional<PrintReportPhoto> choose_report_photo() { return std::nullopt; }
    // Sends the report and writes what the server answered onto the G-code's
    // record; `done` runs later, on the main thread.
    virtual void send_print_report(const PrintReportForm& form, std::function<void(const PrintReportAnswer&)> done) {}

    // First-run onboarding. Each is a whole step of the flow in Home.
    virtual void begin_onboarding()               = 0;
    virtual void dismiss_onboarding()             = 0;
    virtual void defer_profile_import()           = 0;
    virtual void accept_partial_profile_import()  = 0;
    virtual std::string use_detected_profiles(const Snapshot::ProfileSelection& selection) = 0;
    virtual void confirm_onboarding_setup()       = 0;
    virtual void back_onboarding()                = 0;
    virtual void choose_profile_bundle()          = 0;
    virtual void choose_profile_folder()          = 0;
    virtual std::string run_manual_setup()        = 0;
    virtual std::string choose_offline_example()  = 0;
    virtual std::string open_onboarding_example() = 0;
    // Preferences › Agent over Home, the one place the agent is set up.
    virtual void open_agent_setup()               = 0;

    // The printer card's menu. Each returns an empty string when the action
    // ran or the person cancelled it, and otherwise a message for the person,
    // already translated: the request was understood but cannot be carried
    // out, such as a name another profile has.
    virtual std::string open_printer_settings(const std::string& printer_id)                       = 0;
    virtual std::string connect_printer(const std::string& printer_id) { return "Connection is unavailable."; }
    // A calibration of a filament on this printer, in the project chat.
    virtual std::string calibrate_printer(const std::string& printer_id) { return "Calibration is unavailable."; }
    virtual std::string rename_printer(const std::string& printer_id, const std::string& new_name) = 0;
    virtual std::string remove_printer(const std::string& printer_id)                              = 0;
};

}}}} // namespace Slic3r::GUI::JusPrin::Home
#pragma once

// The one place Home meets OrcaSlicer. Everything the gallery and the printer
// rail know is read here and handed on as the fork's own structs; every action
// Home offers is performed here through the upstream entry point that already
// performs it.
//
// Keeping this in one file is the point: MainFrame and the device layer are
// where upstream is actively moving code, so the fork re-derives this file at
// a rebase and nothing else.

#include "HomeBackend.hpp"
#include "PrintHistory.hpp"
#include "PrinterWindow.hpp"

#include <wx/arrstr.h>
#include <wx/weakref.h>

#include <cstdint>
#include <filesystem>
#include <functional>
#include <map>

namespace Slic3r { namespace GUI {
class MainFrame;
}} // namespace Slic3r::GUI
namespace Slic3r::GUI::JusPrin::Workspace {
class ProjectAutosave;
}

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

// Where a file dropped on Home is kept: a temporary copy, since the page
// gives the file's bytes and not its path.
std::filesystem::path dropped_files_folder();

class OrcaHomeBackend final : public IHomeBackend
{
public:
    explicit OrcaHomeBackend(MainFrame& frame);
    ~OrcaHomeBackend() override;

    // How Home opens the printer conversation, which replaces its printers
    // column: an empty name adds a printer, a name changes that one. The
    // shell owns the panel; Home only says what the person asked about.
    using OpenConversation = std::function<void(const std::string& printer_name, bool connect)>;
    void set_conversation_opener(OpenConversation open) { m_open_conversation = std::move(open); }
    // How Home starts a calibration on a printer: the shell asks first, then
    // hands it to the project chat.
    using StartCalibration = std::function<void(const std::string& printer_name, const std::vector<std::string>& spools)>;
    void set_calibration_starter(StartCalibration start) { m_start_calibration = std::move(start); }
    void set_autosave(Workspace::ProjectAutosave* autosave) { m_autosave = autosave; }
    // Told before Home opens one of its projects, for the line a reopened
    // calibration test starts with.
    void set_project_opening(std::function<void()> opening) { m_project_opening = std::move(opening); }
    // Stands in for Open…'s file dialog, for the integration harness: what it
    // returns is what the person chose, nothing for Cancel. Unset, the dialog.
    void set_file_chooser(std::function<wxArrayString()> choose) { m_choose_files = std::move(choose); }

    bool                      dark() const override;
    ProjectList               recent_projects() const override;
    std::vector<PrinterEntry> printers() const override;
    Snapshot::Onboarding onboarding() override;

    void open_project(const std::string& project_id) override;
    void new_project() override;
    void open_file() override;
    void open_dropped_files(const std::vector<DroppedFile>& files) override;
    void launch_monitor(const std::string& printer_id) override;
    void add_printer() override;
    void open_preferences() override;

    void begin_onboarding() override;
    void dismiss_onboarding() override;
    void defer_profile_import() override;
    void accept_partial_profile_import() override;
    std::string use_detected_profiles(const Snapshot::ProfileSelection& selection) override;
    void confirm_onboarding_setup() override;
    void back_onboarding() override;
    void choose_profile_bundle() override;
    void choose_profile_folder() override;
    std::string run_manual_setup() override;
    std::string choose_offline_example() override;
    std::string open_onboarding_example() override;
    void open_agent_setup() override;

    std::string open_printer_settings(const std::string& printer_id) override;
    std::string connect_printer(const std::string& printer_id) override;
    std::string calibrate_printer(const std::string& printer_id) override;
    std::string rename_printer(const std::string& printer_id, const std::string& new_name) override;
    std::string remove_printer(const std::string& printer_id) override;

    nlohmann::json print_history() override;
    void           leave_print_history() override;
    void           open_in_chat(const std::string& project_id, const std::string& conversation_id,
                                const std::string& marker_id) override;
    void           export_gcode(const std::string& project_id, const std::string& hash, const std::string& beside) override;
    void           print_again(const std::string& project_id, const std::string& hash) override;
    bool           reports_offered() const override;
    std::optional<PrintReportPhoto> choose_report_photo() override;
    void           send_print_report(const PrintReportForm& form, std::function<void(const PrintReportAnswer&)> done) override;
    // Stands in for Export…'s file dialog, for the integration harness: the
    // path it returns is the one chosen, empty for Cancel. Unset, the dialog.
    void set_export_chooser(std::function<std::string(const std::string& name)> choose) { m_choose_export = std::move(choose); }
    // The same for a print report's photo.
    void set_report_photo_chooser(std::function<std::string()> choose) { m_choose_report_photo = std::move(choose); }

private:
    // A print host's own page (Mainsail, Fluidd, OctoPrint) in a window of
    // its own; the project's selected printer stays as it is.
    void open_printer_window(const std::string& name);
    // Through the shell, which opens the files in a new project.
    void open_as_new_project(const wxArrayString& files);
    // What only the application knows about the records: preset names as the
    // person sees them, which card a printer is, and the exported files.
    HistoryFacts history_facts() const;
    // Whether an exported file still holds what was written. A file whose
    // size and time are as they were when it was last hashed is not hashed
    // again.
    std::string check_export(const Agent::GcodeDestination& exported) const;

    struct FileCheck
    {
        std::uintmax_t                  size{0};
        std::filesystem::file_time_type written;
        std::string                     hash;
    };
    OnboardingProgress onboarding_progress() const;
    OnboardingFacts onboarding_facts() const;
    bool has_usable_setup() const;
    void save_onboarding(const OnboardingProgress& progress);
    void complete_onboarding();

    MainFrame&                                         m_frame;
    Workspace::ProjectAutosave*                       m_autosave{nullptr};
    OpenConversation                                   m_open_conversation;
    StartCalibration                                   m_start_calibration;
    std::function<void()>                              m_project_opening;
    std::function<wxArrayString()>                     m_choose_files;
    std::function<std::string(const std::string&)>     m_choose_export;

