#pragma once

// The first-run sequence, Welcome → Printers → Home, as a pure step function.
// The Orca adapter stores the progress and supplies the facts; this model
// only decides which screen is in front.
//
// Every door on the welcome is a detour that comes back into the sequence:
// signing in waits on the welcome's card, Preferences closes back onto it,
// and "Just slice for now" skips the detour, not the sequence. Each ends by
// leaving the welcome. Back on the Printers step returns to the welcome, and
// whatever the person finished there stays finished, because it is stored as
// the agent's own settings, not here. Onboarding is done only once Home is
// reached; until then every launch starts at the step the person left.

namespace Slic3r::GUI::JusPrin::Home {

enum class OnboardingStatus { Unfinished, Completed };
enum class OnboardingStep { Hidden, Welcome, Printers };
// Which Printers screen: bring the printers from OrcaSlicer, or the
// add-printer form with "Skip, use a default".
enum class PrintersScreen { OrcaImport, AddPrinter };

struct OnboardingProgress
{
    OnboardingStatus status{OnboardingStatus::Unfinished};
    // The welcome was left through one of its doors. Back clears it.
    bool welcome_left{false};
    // "Start fresh" on the OrcaSlicer screen: the add-printer form instead.
    bool fresh_start{false};
    // A printer was imported, added or assumed on the Printers step.
    bool printer_chosen{false};
};

struct OnboardingFacts
{
    // A JusPrin v1 import ran: its own window greets them over Home and
    // brought their printers, so the Printers step is skipped.
    bool v1_imported{false};
    // A file opened before the sequence finished set the printer, which the
    // chip names "from the file".
    bool printer_from_file{false};
    // An OrcaSlicer folder on this computer holds printers to bring.
    bool orca_printers{false};
};

OnboardingStep next_onboarding_step(const OnboardingProgress& progress, const OnboardingFacts& facts);
PrintersScreen printers_screen(const OnboardingProgress& progress, const OnboardingFacts& facts);

// What Home's Agent group shows once the sequence is over: the three doors
// while no agent is set up, the account and its credits once after signing
// in, and nothing otherwise.
enum class HomeAgentCard { None, Doors, Account };
HomeAgentCard home_agent_card(bool agent_configured, bool signed_in, bool account_card_dismissed);

const char* to_string(OnboardingStatus status);
const char* to_string(OnboardingStep step);
const char* to_string(PrintersScreen screen);
const char* to_string(HomeAgentCard card);

} // namespace Slic3r::GUI::JusPrin::Home

#include "OnboardingModel.hpp"

namespace Slic3r::GUI::JusPrin::Home {

OnboardingStep next_onboarding_step(const OnboardingProgress& progress, const OnboardingFacts& facts)
{
    if (progress.status != OnboardingStatus::Unfinished)
        return OnboardingStep::Hidden;
    // The welcome shows once whatever is already set up: a v1 account, a
    // key, or a file opened at launch.
    if (!progress.welcome_left)
        return OnboardingStep::Welcome;
    // The app needs one printer, and each of these brought one.
    if (progress.printer_chosen || facts.v1_imported || facts.printer_from_file)
        return OnboardingStep::Hidden;
    return OnboardingStep::Printers;
}

PrintersScreen printers_screen(const OnboardingProgress& progress, const OnboardingFacts& facts)
{
    return facts.orca_printers && !progress.fresh_start ? PrintersScreen::OrcaImport : PrintersScreen::AddPrinter;
}

HomeAgentCard home_agent_card(bool agent_configured, bool signed_in, bool account_card_dismissed)
{
    if (!agent_configured)
        return HomeAgentCard::Doors;
    return signed_in && !account_card_dismissed ? HomeAgentCard::Account : HomeAgentCard::None;
}

const char* to_string(OnboardingStatus status)
{
    return status == OnboardingStatus::Completed ? "completed" : "unfinished";
}

const char* to_string(OnboardingStep step)
{
    switch (step) {
    case OnboardingStep::Welcome: return "welcome";
    case OnboardingStep::Printers: return "printers";
    case OnboardingStep::Hidden: break;
    }
    return "hidden";
}

const char* to_string(PrintersScreen screen)
{
    return screen == PrintersScreen::OrcaImport ? "orca_import" : "add_printer";
}

const char* to_string(HomeAgentCard card)
{
    switch (card) {
    case HomeAgentCard::Doors: return "doors";
    case HomeAgentCard::Account: return "account";
    case HomeAgentCard::None: break;
    }
    return "none";
}

} // namespace Slic3r::GUI::JusPrin::Home

#include <catch2/catch_all.hpp>

#include "slic3r/GUI/JusPrin/Home/OnboardingModel.hpp"

using namespace Slic3r::GUI::JusPrin::Home;

TEST_CASE("a first launch runs welcome, then printers, then home", "[home][onboarding]")
{
    OnboardingProgress progress;
    OnboardingFacts facts;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Welcome);

    // Any door, "Just slice for now" included, leaves the welcome.
    progress.welcome_left = true;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Printers);

    progress.printer_chosen = true;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Hidden);
}

TEST_CASE("back from printers returns to the welcome", "[home][onboarding]")
{
    OnboardingProgress progress;
    OnboardingFacts facts;
    progress.welcome_left = true;
    REQUIRE(next_onboarding_step(progress, facts) == OnboardingStep::Printers);
    progress.welcome_left = false;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Welcome);
}

TEST_CASE("the welcome shows once even with something already set up", "[home][onboarding]")
{
    OnboardingProgress progress;
    OnboardingFacts facts;
    facts.v1_imported       = true;
    facts.printer_from_file = true;
    facts.orca_printers     = true;
    CHECK(next_onboarding_step(progress, facts) == OnboardingStep::Welcome);
}

TEST_CASE("a v1 import or a file's printer skips the printers step", "[home][onboarding]")
{
    OnboardingProgress progress;
    progress.welcome_left = true;

    OnboardingFacts v1;
    v1.v1_imported = true;
    CHECK(next_onboarding_step(progress, v1) == OnboardingStep::Hidden);

    OnboardingFacts file;
    file.printer_from_file = true;
    CHECK(next_onboarding_step(progress, file) == OnboardingStep::Hidden);
}

TEST_CASE("completed onboarding never shows again", "[home][onboarding]")
{
    OnboardingProgress progress;
    progress.status = OnboardingStatus::Completed;
    CHECK(next_onboarding_step(progress, OnboardingFacts{}) == OnboardingStep::Hidden);
}

TEST_CASE("the printers step offers OrcaSlicer's printers until start fresh", "[home][onboarding]")
{
    OnboardingProgress progress;
    OnboardingFacts facts;
    CHECK(printers_screen(progress, facts) == PrintersScreen::AddPrinter);

    facts.orca_printers = true;
    CHECK(printers_screen(progress, facts) == PrintersScreen::OrcaImport);

    progress.fresh_start = true;
    CHECK(printers_screen(progress, facts) == PrintersScreen::AddPrinter);
}

TEST_CASE("home's agent group follows the agent's setup", "[home][onboarding]")
{
    CHECK(home_agent_card(false, false, false) == HomeAgentCard::Doors);
    // Signed in: the account and its credits, once.
    CHECK(home_agent_card(true, true, false) == HomeAgentCard::Account);
    CHECK(home_agent_card(true, true, true) == HomeAgentCard::None);
    // Your own key or an AI tool: nothing to show.
    CHECK(home_agent_card(true, false, false) == HomeAgentCard::None);
}

