    std::string outcome; // worked|partly|failed
    std::string text;
    std::string photo_id;
};
struct PrintReportAnswer
{
    enum class State { Sent, AlreadySent, Failed };
    State       state{State::Failed};
    int         credits{0};
};
struct ProjectEntry
{
    std::string        id;
    std::string        name;
    std::string        path;
    std::string        thumbnail_url; // empty when no preview is available
    // When the model was last saved, ISO 8601 in UTC; the page says it as
    // "Today", "Yesterday" or a date.
    std::string        updated_at;
    ProjectStatusKind  status_kind{ProjectStatusKind::Unknown};
    std::string        status_text;
    // The card's print-history line; an empty one draws none.
    HistorySummary     history;
    // The card asks how the latest print came out (board 8d).
    bool               report_due{false};
};
// A spool the printer holds, as a connected printer reports its tray. Either
// field may be empty: a tray that reports no colour is still a material the
// card can name.
struct SpoolEntry
{
    std::string material; // the filament type, such as "PLA"
    std::string colour;   // '#RRGGBB'
};
enum class PrinterState { Idle, Printing, Offline };
const char* to_string(PrinterState state);
// What a card stands for, which decides how the page asks about its actions.
// A named printer is one the person added and names in JusPrin; the page
// confirms a rename or removal itself. A device is a Bambu printer on the
// network or the account that no named printer stands for; its rename and
// removal are Orca's own dialogs, which confirm for themselves.
enum class PrinterKind { Named, Device };
const char* to_string(PrinterKind kind);
// What a card's connection line and dot rest on, apart from its words.
// Online and Offline are a Bambu device's: data in the last 30 seconds, or
// verified before and silent now. Connected is a print host's: an address is
// saved, and for a Moonraker host, it answered in the last 30 seconds; a
// Moonraker host that stopped answering is Offline too. None is neither, and
// draws no dot.
enum class ConnectionState { None, Online, Offline, Connected };
const char* to_string(ConnectionState state);
struct PrinterEntry
{
    std::string             id;
    std::string             name;
    PrinterKind             kind{PrinterKind::Named};
    // The card's menu. An action the card cannot offer is sent as false and
    // shown disabled, so the menu keeps its shape.
    bool                    can_open_settings{false};
    bool                    can_rename{false};
    bool                    can_remove{false};
    PrinterState            state{PrinterState::Idle};
    std::string             status_text;
    // Below zero whenever there is no job to report; only a printing printer
    // sends a bar.
    int                     progress_percent{-1};
    // The Connection row: the finished line, the state it rests on, and the
    // transport -- "lan", "cloud", "host", or empty.
    ConnectionState         connection_state{ConnectionState::None};
json state_payload(const Snapshot& snapshot)
{
    json projects = json::array();
    for (const ProjectEntry& project : snapshot.projects)
        projects.push_back(project_json(project));

    json printers = json::array();
    for (const PrinterEntry& printer : snapshot.printers)
        printers.push_back(printer_json(printer));

    const auto& onboarding = snapshot.onboarding;
    return json{
        {"appearance", snapshot.dark ? "dark" : "light"},
        {"projects", std::move(projects)},
        {"projectsProblem", snapshot.projects_problem},
        {"printers", std::move(printers)},
        {"highlightPrinter", snapshot.highlight_printer},
        {"onboarding",
         json{
             {"visible", onboarding.step != OnboardingStep::Hidden},
             {"step", to_string(onboarding.step)},
             {"status", to_string(onboarding.progress.status)},
             {"agentConfigured", onboarding.agent_configured},
             {"profiles",
              json{
                  {"available", onboarding.printer_profiles + onboarding.filament_profiles + onboarding.process_profiles > 0},
                  {"imported", onboarding.facts.profiles_available},
                  {"partialImportPending", onboarding.progress.partial_import_pending},
                  {"failed", onboarding.failed_profiles},
                  {"printerCount", onboarding.printer_profiles},
                  {"filamentCount", onboarding.filament_profiles},
                  {"processCount", onboarding.process_profiles},
                  {"source", onboarding.profile_source},
                  {"printerNames", onboarding.printer_profile_names},
                  {"filamentNames", onboarding.filament_profile_names},
                  {"processNames", onboarding.process_profile_names},
                  {"importedFiles", onboarding.imported_profiles},
              }},
             {"setup",
              json{
                  {"usable", onboarding.facts.usable_setup},
                  {"offlineExample", onboarding.progress.offline_example},
                  {"summary", onboarding.setup_summary},
                  {"printer", onboarding.setup_printer},
                  {"nozzle", onboarding.setup_nozzle},
                  {"plate", onboarding.setup_plate},
                  {"material", onboarding.setup_material},
                  {"process", onboarding.setup_process},
              }},
             {"projectOpen", onboarding.facts.project_open},
         }},
    };
}

}}}} // namespace Slic3r::GUI::JusPrin::Home

