          </div>
        )}
        {(loadedText || swatches.length > 0) && (
          <div className="printer-fact">
            <dt>Loaded</dt>
            <dd className="printer-spools">
              {loadedText && <span className="printer-material">{loadedText}</span>}
              {swatches.map((spool, index) => (
