      <p className="onboarding-source">
        <FolderGlyph />
        <span className="onboarding-source-path">{orca.source}</span>
        {orca.filamentCount > 0 && <span>· {orca.filamentCount === 1 ? '1 filament' : `${orca.filamentCount} filaments`}</span>}
