1	// The Agent page's add-printer form, drawn on Home's Printers step. The form
2	// and its stylesheet belong to the Agent page, whose class names overlap
3	// Home's (.app, the buttons), so it renders in a shadow root that holds the
4	// Agent stylesheet alone. The design tokens are custom properties on the
5	// document, which a shadow root inherits.
6	
7	import { useEffect, useRef } from 'react';
8	import { createRoot } from 'react-dom/client';
9	import type { Root } from 'react-dom/client';
10	import agentStyles from '../../../AgentUI/src/styles.css?inline';
11	import { AddPrinterForm } from '../../../AgentUI/src/components/AddPrinterForm';
12	import type { PrinterFormChoice } from '../../../AgentUI/src/components/AddPrinterForm';
13	import type { PrinterFormInfo } from '../../../AgentUI/src/bridge/protocol';
14	import { applyStaticTokens as applyAgentTokens } from '../../../AgentUI/src/tokens';
15	
16	// In the printer panel the form is a dialog over the conversation; here it is
17	// the step's own card, in the page's flow, with Back and Skip under it.
18	const IN_FLOW = `.chat-dialog-shade { position: static; padding: 0; background: none; overflow: visible; }`;
19	
20	interface Props {
21	  form: PrinterFormInfo;
22	  onAsk: (catalogId: string, nozzle: number) => void;
23	  onFinish: (choice: PrinterFormChoice) => void;
24	  onClose: () => void;
25	}
26	
27	export function PrinterFormHost(props: Props) {
28	  const host = useRef<HTMLDivElement>(null);
29	  const root = useRef<Root>();
30	
31	  useEffect(() => {
32	    // The form's own variables, such as its menus' and fields' sizes.
33	    applyAgentTokens();
34	    const shadow = host.current!.shadowRoot ?? host.current!.attachShadow({ mode: 'open' });
35	    const style = document.createElement('style');
36	    style.textContent = `${agentStyles}\n${IN_FLOW}`;
37	    const mount = document.createElement('div');
38	    shadow.replaceChildren(style, mount);
39	    root.current = createRoot(mount);
40	    return () => {
41	      const unmounting = root.current;
42	      root.current = undefined;
43	      // React refuses to unmount a root while it is rendering this one.
44	      queueMicrotask(() => unmounting?.unmount());
45	    };
46	  }, []);
47	
48	  useEffect(() => {
49	    root.current?.render(<AddPrinterForm {...props} />);
50	  });
51	
52	  return <div ref={host} className="onboarding-printer-form" />;
53	}
